const svg = $('#bloch-svg'), r = $('#bloch-r'), rOut = $('#bloch-r-out'), out = $('#bloch-out');
const W = 620, H = 260;
const B = Math.sqrt(3) / 4;
function render(){
  while(svg.firstChild) svg.removeChild(svg.firstChild);
  svg.appendChild(SVG("rect",{x:0,y:0,width:W,height:H,fill:"var(--bg)"}));
  const cR = +r.value;
  rOut.textContent = cR.toFixed(2);
  // axis: log-radius bar
  const x0 = 60, x1 = W - 30, yc = 130;
  svg.appendChild(SVG("line",{x1:x0,y1:yc,x2:x1,y2:yc,stroke:"var(--mute)","stroke-width":1.2}));
  function xOf(v){ return x0 + v * (x1 - x0); }
  // tick marks
  for(let v = 0; v <= 1.001; v += 0.1){
    const xx = xOf(v);
    svg.appendChild(SVG("line",{x1:xx,y1:yc-5,x2:xx,y2:yc+5,stroke:"var(--mute)"}));
    const t = SVG("text",{x:xx,y:yc+22,"text-anchor":"middle","font-size":11,fill:"var(--mute)"});
    t.textContent = v.toFixed(1);
    svg.appendChild(t);
  }
  // Bloch lower bound marker (cyan)
  const xb = xOf(B);
  svg.appendChild(SVG("line",{x1:xb,y1:yc-50,x2:xb,y2:yc+50,stroke:"var(--cyan)","stroke-width":2,"stroke-dasharray":"4 3"}));
  const lb = SVG("text",{x:xb,y:yc-60,"text-anchor":"middle","font-size":12,fill:"var(--cyan)","font-weight":600});
  lb.textContent = "B \u2265 \u221A3/4 \u2248 0.433";
  svg.appendChild(lb);
  // candidate marker
  const xa = xOf(cR);
  const above = cR >= B;
  const col = above ? "var(--green)" : "var(--pink)";
  svg.appendChild(SVG("circle",{cx:xa,cy:yc,r:8,fill:col,stroke:"var(--ink)","stroke-width":1.5}));
  const cand = SVG("text",{x:xa,y:yc-14,"text-anchor":"middle","font-size":12,fill:col,"font-weight":600});
  cand.textContent = "r = " + cR.toFixed(2);
  svg.appendChild(cand);
  // schematic: f(D) silhouette with candidate sub-disk
  const cx = 145, cy = 200, R = 38;
  svg.appendChild(SVG("circle",{cx:cx,cy:cy,r:R,fill:"none",stroke:"var(--violet)","stroke-width":1.3,"stroke-dasharray":"3 3"}));
  const lab = SVG("text",{x:cx,y:cy+R+16,"text-anchor":"middle","font-size":11,fill:"var(--violet)"});
  lab.textContent = "image f(\u{1D53B})";
  svg.appendChild(lab);
  svg.appendChild(SVG("circle",{cx:cx-6,cy:cy-3,r:R*cR,fill:col,opacity:0.30,stroke:col,"stroke-width":1.3}));
  const lab2 = SVG("text",{x:cx-6,y:cy-3,"text-anchor":"middle","font-size":11,fill:"var(--ink)"});
  lab2.textContent = "univalent sub-disk";
  svg.appendChild(lab2);
  // header
  const hd = SVG("text",{x:x0,y:30,"font-size":13,fill:"var(--ink)"});
  hd.textContent = "Univalent sub-disk radius in f(\u{1D53B}) for normalized f(0)=0, f\u2032(0)=1";
  svg.appendChild(hd);
  // verdict
  out.textContent = above
    ? "r = " + cR.toFixed(2) + "  \u2265  \u221A3/4  \u2248  0.433  \u2192  consistent with Bloch's bound"
    : "r = " + cR.toFixed(2) + "  <  \u221A3/4  \u2248  0.433  \u2192  below the universal lower bound: every normalized f has image containing a univalent disk of radius \u2265 \u221A3/4";
}
r.addEventListener("input", render);
render();

const svg = $('#nev-svg'), rho = $('#nev-rho'), rhoOut = $('#nev-rho-out'),
      rIn = $('#nev-r'), rOut = $('#nev-r-out'), out = $('#nev-out');
const W = 620, H = 260;
// Toy model: T(r) ~ r^rho.  Split T = m + N with shares depending on rho:
//   rho ~ 1 (e^z-like):  m dominates at infinity (defect at 0 and infinity).
//   rho large (polynomial-like growth in counting): N dominates.
// We use a smooth interpolation.
function shares(r){
  const p = +rho.value;
  // share of N: small for low rho, tends to 1 for very high rho.
  const sN = 1 - Math.exp(-Math.max(0, p - 0.4) * 1.4);
  return { sN, sM: 1 - sN };
}
function Tval(r){
  const p = +rho.value;
  return (p < 1e-3) ? Math.log(1+r) : Math.pow(r, p);
}
function render(){
  while(svg.firstChild) svg.removeChild(svg.firstChild);
  svg.appendChild(SVG("rect",{x:0,y:0,width:W,height:H,fill:"var(--bg)"}));
  rhoOut.textContent = (+rho.value).toFixed(2);
  rOut.textContent = (+rIn.value).toFixed(1);
  // axis
  const x0 = 60, x1 = W - 40, yBase = 220, yTop = 40;
  svg.appendChild(SVG("line",{x1:x0,y1:yBase,x2:x1,y2:yBase,stroke:"var(--mute)"}));
  svg.appendChild(SVG("line",{x1:x0,y1:yBase,x2:x0,y2:yTop,stroke:"var(--mute)"}));
  // sample radii
  const radii = [];
  for(let r = 1; r <= 40; r += 1) radii.push(r);
  const Tmax = Math.max(...radii.map(Tval));
  function xOf(r){ return x0 + (r - 1) * (x1 - x0) / 39; }
  function yOf(v){ return yBase - (v / Tmax) * (yBase - yTop); }
  // bars for m + N (stacked) at sampled radii
      for(let i = 0; i < radii.length; i += 1){
    const r = radii[i];
    const T = Tval(r);
    const { sN, sM } = shares(r);
    const xx = xOf(r) - 5;
    const w = Math.max(2, (x1 - x0) / 40 - 1);
    const yT = yOf(T);
    const ySplit = yOf(T * sN);
    // N (yellow) bottom, m (cyan) top stacked
    svg.appendChild(SVG("rect",{x:xx, y:ySplit, width:w, height:yBase - ySplit, fill:"var(--yellow)", opacity:0.78}));
    svg.appendChild(SVG("rect",{x:xx, y:yT, width:w, height:ySplit - yT, fill:"var(--cyan)", opacity:0.78}));
  }
  // axis labels
  const xl = SVG("text",{x:x1, y:yBase+22, "text-anchor":"end","font-size":11,fill:"var(--mute)"}); xl.textContent = "r"; svg.appendChild(xl);
  const yl = SVG("text",{x:x0-10, y:yTop+10, "text-anchor":"end","font-size":11,fill:"var(--mute)"}); yl.textContent = "T(r,f)"; svg.appendChild(yl);
  // legend
  svg.appendChild(SVG("rect",{x:x0+8, y:yTop-16, width:14, height:10, fill:"var(--cyan)", opacity:0.78}));
  const l1 = SVG("text",{x:x0+28, y:yTop-7, "font-size":12, fill:"var(--ink)"}); l1.textContent = "m(r,\u221E)  proximity"; svg.appendChild(l1);
  svg.appendChild(SVG("rect",{x:x0+170, y:yTop-16, width:14, height:10, fill:"var(--yellow)", opacity:0.78}));
  const l2 = SVG("text",{x:x0+190, y:yTop-7, "font-size":12, fill:"var(--ink)"}); l2.textContent = "N(r,\u221E)  counting"; svg.appendChild(l2);
  // current radius marker
  const r = +rIn.value;
  const xm = xOf(r);
  const T = Tval(r), { sN, sM } = shares(r);
  svg.appendChild(SVG("line",{x1:xm, y1:yBase, x2:xm, y2:yOf(T)-5, stroke:"var(--yellow)", "stroke-dasharray":"3 3", "stroke-width":1.5}));
  out.textContent = "\u03C1 = " + (+rho.value).toFixed(2)
    + "   r = " + r.toFixed(1)
    + "   T(r,f) \u2248 " + T.toFixed(2)
    + "   m \u2248 " + (T*sM).toFixed(2)
    + "   N \u2248 " + (T*sN).toFixed(2)
    + "   defect \u03B4(\u221E) \u2248 " + sM.toFixed(2);
}
rho.addEventListener("input", render);
rIn.addEventListener("input", render);
render();

const svg = $('#berg-svg'), out = $('#berg-out');
const W = 620, H = 320;
const cx = W/2, cy = H/2, R = 130;
// state: w in unit-disk coordinates
let wRe = 0.3, wIm = 0.0;
function pixelToDisk(px, py){
  return [(px - cx) / R, -(py - cy) / R];
}
function diskToPixel(x, y){
  return [cx + x * R, cy - y * R];
}
function render(){
  while(svg.firstChild) svg.removeChild(svg.firstChild);
  svg.appendChild(SVG("rect",{x:0,y:0,width:W,height:H,fill:"var(--bg)"}));
  // sample a grid inside the unit disk and shade by |K(z,w)|^2 = 1/(pi^2 |1 - conj(w) z|^4)
  const N = 56;
  const wAbs = Math.hypot(wRe, wIm);
  let kmax = 1 / Math.pow(Math.PI * Math.pow(1 - wAbs*wAbs, 2), 2);
  if(!isFinite(kmax) || kmax <= 0) kmax = 1;
  for(let i = 0; i < N; i++){
    for(let j = 0; j < N; j++){
      const x = -1 + (2*i + 1)/N;
      const y = -1 + (2*j + 1)/N;
      if(x*x + y*y > 0.99) continue;
      // 1 - conj(w) z = (1 - wRe*x - wIm*y) + i(wRe*y - wIm*x)
      const ar = 1 - wRe*x - wIm*y;
      const ai = wRe*y - wIm*x;
      const denom = Math.pow(ar*ar + ai*ai, 2);
      const k = 1 / (Math.PI * Math.PI * denom);
      const norm = Math.min(1, Math.log(1 + 30*k/kmax) / Math.log(31));
      // mix var(--cyan) and var(--yellow) endpoints (#7de0d6 -> #f0c987) so the heatmap stays palette-aligned
      const t = Math.pow(norm, 0.7);
      const r = Math.round(125 + (240 - 125) * t);   // 7d -> f0
      const g = Math.round(224 + (201 - 224) * t);   // e0 -> c9
      const b = Math.round(214 + (135 - 214) * t);   // d6 -> 87
      const [px, py] = diskToPixel(x, y);
      const cell = (2*R)/N;
      svg.appendChild(SVG("rect",{x:px - cell/2 + 0.5, y:py - cell/2 + 0.5, width:cell, height:cell, fill:`rgb(${r},${g},${b})`, opacity:0.85, "shape-rendering":"crispEdges"}));
    }
  }
  // unit disk boundary
  svg.appendChild(SVG("circle",{cx, cy, r:R, fill:"none", stroke:"var(--mute)", "stroke-width":1.4}));
  // axes
  svg.appendChild(SVG("line",{x1:cx-R-10, y1:cy, x2:cx+R+10, y2:cy, stroke:"var(--mute)", opacity:0.5}));
  svg.appendChild(SVG("line",{x1:cx, y1:cy-R-10, x2:cx, y2:cy+R+10, stroke:"var(--mute)", opacity:0.5}));
  // w marker
  const [wpx, wpy] = diskToPixel(wRe, wIm);
  svg.appendChild(SVG("circle",{cx:wpx, cy:wpy, r:6, fill:"var(--yellow)", stroke:"var(--ink)", "stroke-width":1.5}));
  const wl = SVG("text",{x:wpx+10, y:wpy-8, "font-size":12, fill:"var(--yellow)", "font-weight":600});
  wl.textContent = "w";
  svg.appendChild(wl);
  // header
  const hd = SVG("text",{x:30, y:28, "font-size":13, fill:"var(--ink)"});
  hd.textContent = "|K(z,w)|^2 = 1/(\u03C0\u00B2 |1 \u2212 w\u0304 z|\u2074)  on  \u{1D53B}";
  svg.appendChild(hd);
  // Bergman metric ds^2 at w
  const denom = (1 - wAbs*wAbs);
  const ds2 = 2 / (denom * denom);
  out.textContent = "w = " + wRe.toFixed(3) + " + " + wIm.toFixed(3) + "i,   |w| = " + wAbs.toFixed(3)
    + "   K(w,w) = " + (1/(Math.PI * denom * denom)).toFixed(3)
    + "   Bergman ds\u00B2 = " + ds2.toFixed(3) + " (=2 at w=0; \u2192 \u221E as |w|\u21921)";
}
svg.addEventListener('click', e => {
  const rect = svg.getBoundingClientRect();
  const px = (e.clientX - rect.left) * (W/rect.width);
  const py = (e.clientY - rect.top)  * (H/rect.height);
  const [x, y] = pixelToDisk(px, py);
  if(x*x + y*y < 0.93*0.93){ wRe = x; wIm = y; render(); }
});
render();

const svg = $('#qc-svg'), mre = $('#qc-mre'), mim = $('#qc-mim'),
      mreOut = $('#qc-mre-out'), mimOut = $('#qc-mim-out'), out = $('#qc-out');
const W = 620, H = 280;
function render(){
  while(svg.firstChild) svg.removeChild(svg.firstChild);
  svg.appendChild(SVG("rect",{x:0,y:0,width:W,height:H,fill:"var(--bg)"}));
  const mr = +mre.value, mi = +mim.value;
  mreOut.textContent = mr.toFixed(2);
  mimOut.textContent = mi.toFixed(2);
  const mAbs = Math.hypot(mr, mi);
  const K = (1 + mAbs) / Math.max(1e-9, 1 - mAbs);
  // pre-image: small circle and grid centered at (155, 140)
  const cxL = 155, cyL = 140, scale = 90;
  // post-image: warped versions centered at (465, 140)
  const cxR = 465, cyR = 140;
  function warp(x, y){
    // f(z) = z + mu * conj(z): real(f) = x + mr*x + mi*y;  imag(f) = y - mr*y + mi*x  (since conj(z)=x-iy, mu*conj(z) = (mr+i*mi)(x-iy) = (mr*x+mi*y) + i(mi*x - mr*y))
    const fx = x + mr*x + mi*y;
    const fy = y - mr*y + mi*x;
    return [fx, fy];
  }
  // grid (left)
  for(let g = -1; g <= 1; g += 0.25){
    const path1 = SVG("path",{d:`M ${cxL + (-1)*scale} ${cyL + g*scale} L ${cxL + 1*scale} ${cyL + g*scale}`, stroke:"var(--mute)", "stroke-width":0.7, fill:"none"});
    svg.appendChild(path1);
    const path2 = SVG("path",{d:`M ${cxL + g*scale} ${cyL + (-1)*scale} L ${cxL + g*scale} ${cyL + 1*scale}`, stroke:"var(--mute)", "stroke-width":0.7, fill:"none"});
    svg.appendChild(path2);
  }
  // grid (right, warped)
  for(let g = -1; g <= 1; g += 0.25){
    // horizontal line y = g*scale, x in [-1,1]*scale
    let d = '';
    for(let i = 0; i <= 24; i++){
      const x = -1 + (i/12);
      const [fx, fy] = warp(x, g);
      d += (i === 0 ? 'M ' : 'L ') + (cxR + fx*scale) + ' ' + (cyR - fy*scale) + ' ';
    }
    svg.appendChild(SVG("path",{d, stroke:"var(--cyan)", "stroke-width":0.9, fill:"none", opacity:0.7}));
    let d2 = '';
    for(let i = 0; i <= 24; i++){
      const y = -1 + (i/12);
      const [fx, fy] = warp(g, y);
      d2 += (i === 0 ? 'M ' : 'L ') + (cxR + fx*scale) + ' ' + (cyR - fy*scale) + ' ';
    }
    svg.appendChild(SVG("path",{d:d2, stroke:"var(--cyan)", "stroke-width":0.9, fill:"none", opacity:0.7}));
  }
  // circle (left)
  svg.appendChild(SVG("circle",{cx:cxL, cy:cyL, r:scale*0.6, fill:"none", stroke:"var(--yellow)", "stroke-width":2.0}));
  // circle warped (right)
  let d = '';
  for(let i = 0; i <= 80; i++){
    const t = (i/80) * 2 * Math.PI;
    const x = 0.6*Math.cos(t), y = 0.6*Math.sin(t);
    const [fx, fy] = warp(x, y);
    d += (i === 0 ? 'M ' : 'L ') + (cxR + fx*scale) + ' ' + (cyR - fy*scale) + ' ';
  }
  svg.appendChild(SVG("path",{d, fill:"none", stroke:"var(--yellow)", "stroke-width":2.0}));
  // labels
  const lL = SVG("text",{x:cxL, y:cyL - scale - 18, "text-anchor":"middle", "font-size":13, fill:"var(--ink)"}); lL.textContent = "pre-image"; svg.appendChild(lL);
  const lR = SVG("text",{x:cxR, y:cyR - scale - 18, "text-anchor":"middle", "font-size":13, fill:"var(--ink)"}); lR.textContent = "f(z) = z + \u03BC \u00B7 z\u0304"; svg.appendChild(lR);
  const arr = SVG("path",{d:`M ${cxL + scale + 18} ${cyL} L ${cxR - scale - 18} ${cyL}`, stroke:"var(--violet)", "stroke-width":1.5, fill:"none", "marker-end":"url(#qc-arrow)"});
  let defs = SVG("defs");
  const m = SVG("marker",{id:"qc-arrow", viewBox:"0 0 10 10", refX:9, refY:5, markerWidth:6, markerHeight:6, orient:"auto"});
  m.appendChild(SVG("path",{d:"M0,0 L10,5 L0,10 z", fill:"var(--violet)"}));
  defs.appendChild(m); svg.appendChild(defs);
  svg.appendChild(arr);
  // verdict
  const status = mAbs < 1
    ? `K = (1+|\u03BC|)/(1\u2212|\u03BC|) = ${K.toFixed(2)}  \u2192  ${K.toFixed(2)}-quasiconformal`
    : 'NOT quasiconformal: |\u03BC| \u2265 1 makes f orientation-reversing or singular';
  out.textContent = `\u03BC = ${mr.toFixed(2)} + ${mi.toFixed(2)}i,  |\u03BC| = ${mAbs.toFixed(3)}.  ${status}.`;
}
mre.addEventListener("input", render);
mim.addEventListener("input", render);
render();

const svg = $('#hg-svg'), rIn = $('#hg-r'), rOut = $('#hg-r-out'), out = $('#hg-out');
const W = 620, H = 320;
function render(){
  while(svg.firstChild) svg.removeChild(svg.firstChild);
  svg.appendChild(SVG("rect",{x:0,y:0,width:W,height:H,fill:"var(--bg)"}));
  const r = +rIn.value;
  rOut.textContent = r.toFixed(2);
  // header
  const hd = SVG("text",{x:30, y:32, "font-size":14, fill:"var(--ink)"});
  hd.textContent = "Hartogs figure in \u2102\u00B2: 2D schematic of the polydisk slice";
  svg.appendChild(hd);
  // outer square
  const cx = W/2, cy = 180, S = 110;
  svg.appendChild(SVG("rect",{x:cx-S, y:cy-S, width:2*S, height:2*S, fill:"none", stroke:"var(--mute)", "stroke-width":1.5, "stroke-dasharray":"5 4"}));
  const olbl = SVG("text",{x:cx-S, y:cy-S-8, "font-size":12, fill:"var(--mute)"});
  olbl.textContent = "polydisk \u{1D53B}\u00B2 (full domain)";
  svg.appendChild(olbl);
  // inner square (the 'hole', a smaller polydisk)
  const s = S * r;
  // forced-extension fill (full square minus hole) is the cyan "shell"
  // shell: full square covered, hole appears as the inner cutout
  svg.appendChild(SVG("rect",{x:cx-S, y:cy-S, width:2*S, height:2*S, fill:"var(--cyan)", opacity:0.18}));
  // hole: emphasize it as the place where data is GIVEN -> we know f everywhere outside this in the polydisk
  // Actually conventional Hartogs figure is the shell |z_1|<1, r<|z_2|<1 union r<|z_1|<1, |z_2|<1 etc.
  // We shade: shell = cyan (data given); hole = pink (forced-extension target).
  // Shell uses the cyan we just painted; remove cyan from the hole and paint hole pink.
  svg.appendChild(SVG("rect",{x:cx-s, y:cy-s, width:2*s, height:2*s, fill:"var(--bg)"}));
  svg.appendChild(SVG("rect",{x:cx-s, y:cy-s, width:2*s, height:2*s, fill:"var(--pink)", opacity:0.32, stroke:"var(--pink)", "stroke-width":1.5, "stroke-dasharray":"4 3"}));
  // ring outline
  svg.appendChild(SVG("rect",{x:cx-S, y:cy-S, width:2*S, height:2*S, fill:"none", stroke:"var(--cyan)", "stroke-width":1.6}));
  // legend
  svg.appendChild(SVG("rect",{x:30, y:280, width:14, height:10, fill:"var(--cyan)", opacity:0.5}));
  const l1 = SVG("text",{x:50, y:289, "font-size":12, fill:"var(--ink)"}); l1.textContent = "shell: f given holomorphic"; svg.appendChild(l1);
  svg.appendChild(SVG("rect",{x:240, y:280, width:14, height:10, fill:"var(--pink)", opacity:0.5}));
  const l2 = SVG("text",{x:260, y:289, "font-size":12, fill:"var(--ink)"}); l2.textContent = "hole: extension forced (Hartogs)"; svg.appendChild(l2);
  // arrow from shell into hole
  const arr = SVG("path",{d:`M ${cx + s + 16} ${cy} L ${cx + s - 8} ${cy}`, stroke:"var(--yellow)", "stroke-width":1.6, fill:"none", "marker-end":"url(#hg-arrow)"});
  let defs = SVG("defs");
  const m = SVG("marker",{id:"hg-arrow", viewBox:"0 0 10 10", refX:9, refY:5, markerWidth:6, markerHeight:6, orient:"auto"});
  m.appendChild(SVG("path",{d:"M0,0 L10,5 L0,10 z", fill:"var(--yellow)"}));
  defs.appendChild(m); svg.appendChild(defs);
  svg.appendChild(arr);
  const v4 = Math.pow(r, 4);
  const bm = Math.pow(r, 3);
  out.textContent =
    `inner radius r = ${r.toFixed(2)}\ninner 4-volume / full polydisk = r\u2074 \u2248 ${v4.toFixed(3)}\nshell 4-volume / full polydisk = 1 \u2212 r\u2074 \u2248 ${(1 - v4).toFixed(3)}\nBochner\u2013Martinelli boundary measure on \u2202K scales \u223C r\u00B3 \u2248 ${bm.toFixed(3)}\n(\u2192 0 as r \u2192 0, making the extension formula \u2018obvious\u2019 in that limit).\nAny holomorphic f on the cyan shell extends uniquely to the pink hole \u2014 isolated singularities are forbidden in \u2102\u00B2.`;
}
rIn.addEventListener("input", render);
render();
